SET LOCAL search_path = "pnl", pg_catalog;
CREATE TABLE "pnl".authority_credentials(credential_id uuid PRIMARY KEY,actor_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('user','infrastructure','finance','moderator','support')),scopes text[] NOT NULL CHECK(cardinality(scopes)>0 AND cardinality(scopes)<=32),token_hash bytea NOT NULL UNIQUE CHECK(octet_length(token_hash)=32),session_id uuid CHECK(role<>'user' OR session_id IS NOT NULL),expires_at timestamptz NOT NULL,revoked_at timestamptz);
REVOKE ALL ON "pnl"."authority_credentials" FROM PUBLIC;
CREATE VIEW pnl.authority_credentials_v2 AS SELECT c.credential_id,c.actor_id,c.role,c.scopes,c.token_hash,c.session_id,c.expires_at,c.revoked_at FROM pnl.authority_credentials c
WHERE (c.role='user' AND c.session_id IS NOT NULL AND EXISTS(SELECT 1 FROM users.identity_sessions_v2 s JOIN users.identity_accounts_v2 a USING(account_id) JOIN users.identity_wallet_links_v2 w ON w.account_id=a.account_id AND w.wallet=s.wallet AND w.chain_id=125 AND w.state='verified' WHERE s.session_id=c.session_id AND s.account_id=c.actor_id AND s.access_hash=c.token_hash AND s.revoked_at IS NULL AND s.access_expires_at>clock_timestamp() AND s.auth_epoch=a.auth_epoch)) OR (c.role<>'user' AND c.session_id IS NOT NULL AND EXISTS(SELECT 1 FROM security.operator_sessions_v2 o WHERE o.session_id=c.session_id::text AND o.actor=c.actor_id::text AND o.audience='control' AND NOT o.revoked AND o.issued_at<=clock_timestamp() AND o.expires_at>clock_timestamp() AND o.expires_at>o.issued_at AND o.expires_at-o.issued_at<=interval '15 minutes' AND o.mfa_expires_at>clock_timestamp() AND o.mfa_expires_at<=clock_timestamp()+interval '5 minutes'));
CREATE VIEW pnl.identity_control_wallets_v2 AS SELECT account_id AS actor_id,account_id,wallet,chain_id,state FROM users.identity_wallet_links_v2;
REVOKE ALL ON pnl.authority_credentials_v2,pnl.identity_control_wallets_v2 FROM PUBLIC;
